(NULL, 'novo_pedido', 'Pedido #{{pedido_id}} recebido - Braziliana',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Pedido recebido!</strong> Seu pedido <strong>#{{codigo_pedido}}</strong> foi registrado com sucesso.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Obrigado pela sua compra! Estamos processando seu pedido e voce recebera atualizacoes por email.</p><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f9fa;border-radius:6px;margin-bottom:24px;"><tr><td style="padding:20px;"><table width="100%" cellpadding="4" cellspacing="0"><tr><td style="font-size:13px;color:#666;padding:4px 0;">Pedido:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">#{{codigo_pedido}}</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Data:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">{{data_pedido}}</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Moeda:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">{{moeda}}</td></tr><tr><td style="font-size:14px;color:#333;font-weight:700;padding:8px 0 4px;">Total:</td><td style="font-size:16px;color:#1a2332;font-weight:700;padding:8px 0 4px;text-align:right;">{{valor_total}}</td></tr></table></td></tr></table><p style="font-size:14px;color:#555;margin:0 0 20px;"><strong>Itens:</strong><br>{{itens}}</p><p style="font-size:14px;color:#555;margin:0 0 20px;"><strong>Endereco de entrega:</strong><br>{{endereco_entrega}}</p><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'pedido_aprovado', 'Pedido #{{codigo_pedido}} aprovado - Braziliana',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Pagamento aprovado!</strong> Seu pedido <strong>#{{codigo_pedido}}</strong> foi confirmado.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Seu pagamento foi processado com sucesso. Estamos preparando seu pedido para envio.</p><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f9fa;border-radius:6px;margin-bottom:24px;"><tr><td style="padding:20px;"><table width="100%" cellpadding="4" cellspacing="0"><tr><td style="font-size:13px;color:#666;padding:4px 0;">Pedido:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">#{{codigo_pedido}}</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Data aprovacao:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">{{data_aprovacao}}</td></tr><tr><td style="font-size:14px;color:#333;font-weight:700;padding:8px 0 4px;">Total:</td><td style="font-size:16px;color:#1a2332;font-weight:700;padding:8px 0 4px;