(NULL, 'novo_usuario', 'Bem-vindo a Braziliana, {{usuario_nome}}!',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{usuario_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Bem-vindo!</strong> Sua conta foi criada com sucesso na Braziliana Shop.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Estamos felizes em te-lo conosco! Agora voce pode navegar por nossos produtos, fazer compras e acompanhar seus pedidos.</p><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f9fa;border-radius:6px;margin-bottom:24px;"><tr><td style="padding:20px;"><table width="100%" cellpadding="4" cellspacing="0"><tr><td style="font-size:13px;color:#666;padding:4px 0;">Email:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">{{usuario_email}}</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Data cadastro:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">{{data_cadastro}}</td></tr></table></td></tr></table><p style="font-size:14px;color:#555;margin:0 0 20px;">Explore nosso catalogo e encontre os melhores produtos com envio internacional.</p><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'recuperar_senha', 'Recuperacao de senha - Braziliana',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{usuario_nome}}</strong>!</p><div style="background-color:#fff3cd;border-left:4px solid #ffc107;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#856404;font-size:14px;"><strong>Solicitacao de nova senha:</strong> Recebemos um pedido para redefinir sua senha.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Se voce solicitou a recuperacao de senha, utilize o codigo abaixo para criar uma nova senha:</p><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f9fa;border-radius:6px;margin-bottom:24px;"><tr><td style="padding:20px;text-align:center;"><p style="font-size:12px;color:#666;margin:0 0 8px;">Seu codigo de recuperacao:</p><p style="font-size:24px;color:#1a2332;font-weight:700;margin:0;letter-spacing:3px;">{{token_reset}}</p></td></tr></table><p style="font-size:14px;color:#555;margin:0 0 20px;">Este codigo expira em 1 hora. Se voce nao solicitou a recuperacao de senha, ignore este email.</p><p style="font-size:13px;color:#888;margin:0 0 8px;"><strong>Dados da solicitacao:</strong></p><p style="font-size:13px;color:#888;margin:0 0 4px;">Email: {{usuario_email}}</p><p style="font-size:13px;color:#888;margin:0 0 20px;">Data: {{data_solicitacao}}</p><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

